import java.util.Map;
import java.util.TreeMap;

public class FieldInspectorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object at(Map<String, Object> map, String key) {
        return map == null ? null : map.get(key);
    }

    public static void main(String[] args) {
        try {
            Map<String, Object> snap = FieldInspector.snapshot(new Sample("gizmo", 7, false, 1.25));

            check("map size", 4, snap == null ? null : Integer.valueOf(snap.size()));
            check("String field", "gizmo", at(snap, "name"));
            check("int field is boxed to Integer", 7, at(snap, "count"));
            check("boolean field", false, at(snap, "active"));
            check("double field", 1.25, at(snap, "price"));
            check("sorted field names", "[active, count, name, price]",
                    snap == null ? null : new TreeMap<>(snap).keySet().toString());

            Map<String, Object> other = FieldInspector.snapshot(new Sample("bolt", -3, true, 0.5));
            check("a second object gets its own values", "bolt/-3/true/0.5",
                    at(other, "name") + "/" + at(other, "count") + "/"
                            + at(other, "active") + "/" + at(other, "price"));

            Map<String, Object> empty = FieldInspector.snapshot(new Object());
            check("an object with no declared fields", 0,
                    empty == null ? null : Integer.valueOf(empty.size()));
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected " + t.getClass().getSimpleName() + ": " + t.getMessage());
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

